fn str_len(s: &Str) -> Int {
    let mut l = 0
    for _ in chars(s) {
        l = l + 1
    }
    l
}

fn chars(s: &Str) -> Vec<Str> {
    let mut v = vec()
    let mut i = 0
    while i < str_len(s) {
        let c = s.chars().nth(i).unwrap()
        v.push(c.to_string())
        i = i + 1
    }
    v
}

