fn total(v: Vec<Int>, flag: Bool) -> Int {
    let w = v
    if flag {
        return len(w) * 10
    }
    let u = v.clone()
    push(u, 3)
    len(u) * 20
}

fn main() {
    print(total(push(push(vec(), 1), 2), true))
    print(total(push(push(vec(), 1), 2), false))
}

fn total(v: Vec<Int>, flag: Bool) -> Int {
    let w = v
    if flag {
        let r = len(&w) * 10
        drop w
        return r
    }
    let u = push(v, 3)
    let r = len(&u) * 20
    drop u
    r
}

fn main() {
    print(total(push(push(vec(), 1), 2), true))
    print(total(push(push(vec(), 1), 2), false))
}

fn total(v: Vec<i32>, flag: bool) -> usize {
    let w = v.clone(); // Clone v to avoid ownership error
    if flag {
        return w.len() * 10;
    }
    let mut u = v;
    u.push(3);
    u.len() * 20
}

fn main() {
    println!("{}", total(vec![1, 2], true));
    println!("{}", total(vec![1, 2], false));
}

fn f(o: Option<Vec<Int>>) -> Option<Int> {
    let v = o.clone()?
    let w = o.clone()?
    Some(len(v) * 10 + len(w))
}

fn main() {
    match f(Some(push(push(vec(), 1), 2))) {
        Some(n) => print(n),
        None => print(0),
    }
    match f(None) {
        Some(n) => print(n),
        None => print(99),
    }
}

fn f(o: Option<Vec<Int>>) -> Option<Int> {
    let v = o?
    let w = o?
    let r = len(&v) * 10 + len(&w)
    drop v
    drop w
    Some(r)
}

fn main() {
    match f(Some(push(push(vec(), 1), 2))) {
        Some(n) => print(n),
        None => print(0),
    }
    match f(None) {
        Some(n) => print(n),
        None => print(99),
    }
}

fn f(o: Option<Vec<i32>>) -> Option<usize> {
    let v = o.clone()?;
    let w = o?;
    Some(v.len() * 10 + w.len())
}

fn main() {
    match f(Some(vec![1, 2])) {
        Some(n) => println!("{}", n),
        None => println!("0"),
    }
    match f(None) {
        Some(n) => println!("{}", n),
        None => println!("99"),
