    drop w
    Some(r)
}

fn main() {
    match f(Some(push(push(vec(), 1), 2))) {
        Some(n) => print(n),
        None => print(0),
    }
    match f(None) {
        Some(n) => print(n),
        None => print(99),
    }
}

fn f(o: Option<Vec<i32>>) -> Option<usize> {
    let v = o?;
    let w = o.clone()?;
    Some(v.len() * 10 + w.len())
}

fn main() {
